            if (this.currentLine >= this.lines.length) {
                return null;
            }
            this.tokens = this.lines[this.currentLine++].split(/\s+/);
            this.currentToken = 0;
        }
        return this.tokens[this.currentToken++];
    }

    nextInt() {
        return parseInt(this.next(), 10);
    }

    nextLong() {
        return BigInt(this.next());
    }
